function navigateNetwork(e){
 e.preventDefault();const input=el('network-url');let url;
 try{url=new URL(input.value.includes('://')?input.value:'https://'+input.value);}catch{input.setCustomValidity('Enter https://www.example.com/hello');input.reportValidity();return;}
 if(url.protocol!=='https:'||!['www.example.com','typo.example.com'].includes(url.hostname)||url.port||url.username||url.password||url.pathname!=='/hello'||url.search||url.hash){input.setCustomValidity('Use https://www.example.com/hello or https://typo.example.com/hello in this simulation.');input.reportValidity();return;}
 input.setCustomValidity('');input.value=url.href;
 if(url.hostname==='typo.example.com')el('scenario').value='failure';else if(el('scenario').value==='failure')el('scenario').value='cold';
 el('scenario').dispatchEvent(new Event('change'));el('send').click();
}
el('network-address-form').addEventListener('submit',navigateNetwork);
el('network-reload').addEventListener('click',navigateNetwork);
