function configureAPI(){clearInterval(apiTimer);apiTimer=null;apiStep=0;request=null;const mode=el('api-scenario').value;el('api-method').value=['create','invalid'].includes(mode)?'POST':'GET';el('api-path').value=mode==='missing'?'/api/missing':'/api/notes';if(mode==='invalid')el('note-text').value='';el('note-text').disabled=!['create','invalid'].includes(mode);drawAPI();drawBrowser();}
function beginAPI(){const mode=el('api-scenario').value;request={mode,method:el('api-method').value,path:el('api-path').value,text:el('note-text').value.trim(),committed:false};apiStep=1;drawAPI();drawBrowser();}
function responseFor(r){if(r.mode==='auth')return [401,{error:'Login required'}];if(r.mode==='missing')return [404,{error:'Route not found'}];if(r.mode==='offline')return [503,{error:'Service unavailable'}];if(r.method==='POST'&&!r.text)return [422,{error:'Note text must not be empty'}];return r.method==='POST'?[201,{id:notes.length,text:r.text}]:[200,{notes:[...notes]}];}
function nextAPI(){if(!request||apiStep>=6){beginAPI();return;}apiStep++;if(apiStep===4){if(request.method==='POST'&&responseFor(request)[0]===201&&!request.committed){notes.push(request.text);request.committed=true;}request.response=responseFor(request);}drawAPI();drawBrowser();}
function drawAPI(){drawRequestGuide();document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',apiStep===1||apiStep===6?b.dataset.role==='frontend':apiStep===3?b.dataset.role==='backend':apiStep===4?b.dataset.role===(request?.response?.[0]<300?'database':'backend'):false));for(const n of [1,2]){const w=el('api-wire-'+n);w.classList.toggle('active',n===1?[2,5].includes(apiStep):apiStep===4&&request?.response?.[0]<300);w.classList.toggle('returning',apiStep===5);}el('api-request').textContent=request?`${request.method} ${request.path}\nAccept: application/json\n${request.mode==='auth'?'(No session cookie)':'Cookie: session=demo'}${request.method==='POST'?'\nContent-Type: application/json\n\n'+JSON.stringify({text:request.text},null,2):''}`:'Choose a scenario to inspect its request.';el('api-response').textContent=apiStep>=4?`HTTP ${request.response[0]}\nContent-Type: application/json\n\n${JSON.stringify(request.response[1],null,2)}`:'Waiting for a response…';el('api-check-request').classList.toggle('done',apiStep>=1);el('api-check-server').classList.toggle('done',apiStep>=4);el('api-check-response').classList.toggle('done',apiStep>=6);if(apiStep>0&&apiStep<6)el('api-screen').textContent='Loading…';else if(apiStep===6){if(request.response[0]>=400)el('api-screen').textContent=`Could not load or save notes: ${request.response[1].error}.`;else{const ul=document.createElement('ul');for(const text of notes){const li=document.createElement('li');li.textContent=text;ul.append(li);}el('api-screen').replaceChildren(ul);}}else el('api-screen').textContent='Your notes appear here after a successful request.';}
