function drawFinder(){
 const names=shell.children(shell.cwd,true).sort((a,b)=>Number(shell.dirs.has(shell.path(b)))-Number(shell.dirs.has(shell.path(a)))||a.localeCompare(b));
 el('finder-path').textContent=shell.cwd;el('finder-up').disabled=shell.cwd==='/';el('finder-inspector').hidden=true;
 el('finder-home').setAttribute('aria-current',shell.cwd===shell.home?'location':'false');el('finder-project').setAttribute('aria-current',shell.cwd===shell.home+'/project'?'location':'false');
 const hiddenCount=names.filter(name=>name.startsWith('.')).length;
 el('finder-count').textContent=`${names.length} item${names.length===1?'':'s'}${hiddenCount?' · '+hiddenCount+' hidden':''}`;
 el('shell-files').replaceChildren(...names.map(name=>{
  const folder=shell.dirs.has(shell.path(name)),hidden=name.startsWith('.'),li=document.createElement('li'),button=document.createElement('button');
  button.className='finder-item'+(hidden?' is-hidden':'');button.setAttribute('aria-label',`${name}, ${hidden?'hidden ':''}${folder?'folder':'file'}`);button.setAttribute('aria-pressed','false');
  const icon=document.createElement('span');icon.className='finder-icon';icon.innerHTML=finderIcon(folder)+(hidden?finderEye:'');
  const label=document.createElement('span');label.className='finder-name';label.textContent=name;button.append(icon,label);
  button.addEventListener('click',()=>{document.querySelectorAll('.finder-item').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));el('finder-selection').textContent=name+(hidden?' · Hidden':'');el('finder-contents').textContent=folder?'Double-click or press Enter to open this folder.':shell.read(name);el('finder-inspector').hidden=false;});
  if(folder){button.addEventListener('dblclick',()=>finderNavigate(name));button.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();finderNavigate(name);}});}
  li.append(button);return li;
 }));
 if(!names.length){const empty=document.createElement('li');empty.className='finder-empty';empty.textContent='This folder is empty.';el('shell-files').append(empty);}
}
