 const recipeRun=line.trim()==='make hello'&&/\t(?:sh|bash) scripts\/hello\.sh/.test(work.read('Makefile'));
 if(scenario.id==='test'&&result.code&&result.output.includes('FAIL:'))seenFailure=true;
