 if(devRun&&!result.code&&result.output.includes('Formatted')&&result.output.includes('PASS:')&&result.output.includes('Serving'))chainSuccess=true;
 if(devRun&&result.code&&result.output.includes('FAIL:')&&!result.output.includes('Built dist')&&!result.output.includes('Serving'))chainFailure=true;
 const pass={hello:greeting&&scriptRun,recipe:greeting&&recipeRun,serve:savedEdit&&builtEdit&&skipped&&servedEdit,test:seenFailure&&!result.code&&result.output.includes('PASS:'),chain:chainSuccess&&chainFailure}[scenario.id];
 if(pass)completedScenarios.add(scenario.id);
